    clearPolling();
    state.pollAttempts = 0;
    state.pollingTimer = window.setInterval(() => {
      if (document.visibilityState === 'hidden') {
        return;
      }
      state.pollAttempts += 1;
      if (state.pollAttempts > POLL_MAX_ATTEMPTS) {
        clearPolling();
        setStatus('');
        return;
      }
      void loadMessages().catch((error) => {
        setStatus(error.message || 'Could not refresh the conversation.');
        clearPolling();
      });
    }, POLL_INTERVAL_MS);
  }

  function clearPolling() {
    if (state.pollingTimer) {
      window.clearInterval(state.pollingTimer);
      state.pollingTimer = null;
    }
    state.pollAttempts = 0;
  }

  function updateTokenPressureBanner(level) {
    const host = document.getElementById('clancy-assistant-token-banner');
    if (!host) {
      return;
    }
    if (level === 'warning') {
      host.hidden = false;
      host.className = 'clancy-assistant-token-banner clancy-assistant-token-banner-warning';
